function useReveal() {
  useEffect(() => {
    const els = document.querySelectorAll(".cg-reveal");
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) {
            const el = e.target;
            const delay = parseInt(el.getAttribute("data-d") || "0", 10);
            setTimeout(() => el.classList.add("in"), delay);
            io.unobserve(el);
          }
        });
      },
      { threshold: 0.12 }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  });
}

function Reveal({ children, delay = 0, className = "" }) {
  return (
    <div className={`cg-reveal ${className}`} data-d={delay}>
      {children}
    </div>
  );
}

