/* ---------------- CONTACT PAGE ---------------- */
function Contact() {
  const [form, setForm] = useState({ name: "", email: "", goal: "2 Days / Week + Diet", message: "" });
  const [errors, setErrors] = useState({});
  const [sent, setSent] = useState(false);
  const [sending, setSending] = useState(false);
  const [failed, setFailed] = useState(false);

  const set = (k) => (e) => setForm((f) => ({ ...f, [k]: e.target.value }));

  const submit = async () => {
    const er = {};
    if (!form.name.trim()) er.name = true;
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) er.email = true;
    if (!form.message.trim()) er.message = true;
    setErrors(er);
    if (Object.keys(er).length > 0) return;

    setSending(true);
    setFailed(false);
    try {
      const res = await fetch(FORMSPREE_ENDPOINT, {
        method: "POST",
        headers: { "Content-Type": "application/json", Accept: "application/json" },
        body: JSON.stringify({
          name: form.name,
          email: form.email,
          interest: form.goal,
          message: form.message,
          _subject: `New training inquiry from ${form.name}`,
        }),
      });
      if (res.ok) setSent(true);
      else setFailed(true);
    } catch (e) {
      setFailed(true);
    }
    setSending(false);
  };

  return (
    <>
      <header className="cg-section" style={{ paddingBottom: 60 }}>
        <div className="cg-wrap">
          <Reveal>
            <div className="cg-kicker">Get In Touch</div>
          </Reveal>
          <Reveal delay={80}>
            <h1 className="cg-h2" style={{ fontSize: "clamp(48px,9vw,120px)", marginBottom: 24 }}>
              Let's get
              <br />
              <span style={{ color: "var(--red)" }}>to work.</span>
            </h1>
          </Reveal>
          <Reveal delay={150}>
            <p className="cg-lead">
              Tell me a little about your goals and I'll get back to you within 24 hours to set up your free consult.
            </p>
          </Reveal>
        </div>
      </header>

      <section style={{ paddingBottom: 110 }}>
        <div className="cg-wrap cg-contact-grid">
          {/* FORM */}
          <Reveal>
            <div>
              {sent ? (
                <div className="cg-success">
                  <div className="ic">
                    <Check size={30} />
                  </div>
                  <h3>Message sent</h3>
                  <p>
                    Thanks, {form.name.split(" ")[0] || "there"} — your message is on its way. Chris will be in touch
                    within 24 hours.
                  </p>
                </div>
              ) : (
                <div>
                  <div className="cg-field">
                    <label>Your Name</label>
                    <input
                      className={errors.name ? "cg-err" : ""}
                      value={form.name}
                      onChange={set("name")}
                      placeholder="Jordan Smith"
                    />
                  </div>
                  <div className="cg-field">
                    <label>Email</label>
                    <input
                      className={errors.email ? "cg-err" : ""}
                      value={form.email}
                      onChange={set("email")}
                      placeholder="you@email.com"
                    />
                  </div>
                  <div className="cg-field">
                    <label>I'm interested in</label>
                    <select value={form.goal} onChange={set("goal")}>
                      {PLAN_TITLES.map((t) => (
                        <option key={t}>{t}</option>
                      ))}
                      <option>Not sure yet</option>
                    </select>
                  </div>
                  <div className="cg-field">
                    <label>Tell me about your goals</label>
                    <textarea
                      className={errors.message ? "cg-err" : ""}
                      value={form.message}
                      onChange={set("message")}
                      placeholder="What do you want to achieve? Any history, injuries, or timeline I should know about?"
                    />
                  </div>
                  <button
                    className="cg-btn cg-btn-primary"
                    onClick={submit}
                    disabled={sending}
                    style={{ width: "100%", justifyContent: "center", padding: "17px", opacity: sending ? 0.7 : 1 }}
                  >
                    {sending ? "Sending…" : "Send Message"} <Send size={16} />
                  </button>
                  {failed && (
                    <p style={{ color: "var(--red)", fontSize: 14, marginTop: 12, fontWeight: 600 }}>
                      Something went wrong — please try again, or email chrisgtrainer@outlook.com directly.
                    </p>
                  )}
                </div>
              )}
            </div>
          </Reveal>

          {/* INFO */}
          <Reveal delay={120}>
            <div>
              <div className="cg-info-card">
                <div className="cg-info-row">
                  <div className="cg-info-ico">
                    <Mail size={20} />
                  </div>
                  <div>
                    <b>Email</b>
                    <span>chrisgtrainer@outlook.com</span>
                  </div>
                </div>
                <div className="cg-info-row">
                  <div className="cg-info-ico">
                    <MapPin size={20} />
                  </div>
                  <div>
                    <b>Studio</b>
                    <span>Power Shack Gym, Hilliard</span>
                  </div>
                </div>
                <div className="cg-info-row">
                  <div className="cg-info-ico">
                    <Clock size={20} />
                  </div>
                  <div>
                    <b>Hours</b>
                    <span>Mon–Sat · 6:00am – 7:00pm</span>
                  </div>
                </div>
              </div>
              <div className="cg-info-card">
                <b style={{ fontFamily: "Archivo", fontSize: 13, letterSpacing: 1.5, textTransform: "uppercase", color: "var(--muted)", display: "block", marginBottom: 16 }}>
                  Follow the pack
                </b>
                <div className="cg-socials">
                  {SOCIALS.map((soc) => {
                    const Ic = soc.icon;
                    return (
                      <a
                        key={soc.label}
                        className="cg-soc"
                        href={soc.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        aria-label={soc.label}
                      >
                        <Ic size={20} />
                      </a>
                    );
                  })}
                </div>
              </div>
            </div>
          </Reveal>
        </div>
      </section>
    </>
  );
}

